arguments.command:
for f in sample_14.h5 sample_20.h5; do echo "=================== $f ==================="; python3 -I -c "
import h5py, json, sys
with h5py.File(sys.argv[1], 'r') as fh:
    print('root attrs:', list(fh.attrs.keys()))
    for k in fh.attrs:
        v = fh.attrs[k]
        if k == 'model_config':
            if isinstance(v, bytes): v = v.decode()
            print(json.dumps(json.loads(v), indent=1)[:4000])
        else:
            print(k, '=', repr(v)[:200])
    def visit(name, obj):
        print('  ', name, type(obj).__name__, dict(obj.attrs) if len(obj.attrs) < 5 else list(obj.attrs.keys()))
    fh.visititems(visit)
" "$f" 2>&1 | head -150; done

