arguments.command:
for f in sample_15.keras sample_28.keras; do echo "=================== $f ==================="; python3 -I -c "
import zipfile, io, json, sys
zf = zipfile.ZipFile(sys.argv[1])
for zi in zf.infolist():
    print(zi.filename, zi.file_size, zi.compress_type)
for n in ('config.json', 'metadata.json'):
    try:
        print('---', n)
        print(json.dumps(json.loads(zf.read(n)), indent=1)[:5000])
    except Exception as e: print('ERR', e)
" "$f" 2>&1 | head -200; done

