                    called.append((nm,fn,'args'))
                    stack.append(Obj('inst'))
                elif nm in ('NEWOBJ','NEWOBJ_EX'):
                    if nm=='NEWOBJ_EX': stack.pop()
                    args=stack.pop(); cls=stack.pop()
                    called.append(('NEWOBJ',cls,'__new__only'))
                    stack.append(Obj('newobj'))
                elif nm=='BUILD':
                    state=stack.pop(); obj=stack[-1] if stack else None
                    called.append(('BUILD',obj,'setstate'))
                elif nm=='STOP':
                    break
                else:
                    # unknown: leave stack
                    pass
        except Exception as e:
            err=str(e)
        res.append((pos,called,err))
        pos += last+1
        if err: break
    return res

